import { Client } from "@modelcontextprotocol/sdk/client/index.js"

function fakeTransport(start) {
	const t = {
		start,
		close: async () => {},
		send: async () => {},
	}
	return t
}

const client = new Client({ name: "reuse-check", version: "1.0.0" })
try {
	await client.connect(fakeTransport(async () => {
		throw new Error("transport refused")
	}))
} catch (e) {
	console.log("first connect failed:", e.message)
}
await client.close().catch(() => {})
try {
	await client.connect(fakeTransport(async () => {}))
	console.log("second connect: succeeded")
} catch (e) {
	console.log("second connect failed:", e.message)
}

