import assert from "node:assert/strict";
import { Client } from "../toolchain/node_modules/@modelcontextprotocol/sdk/dist/esm/client/index.js";
import { StreamableHTTPClientTransport } from "../toolchain/node_modules/@modelcontextprotocol/sdk/dist/esm/client/streamableHttp.js";
import { LATEST_PROTOCOL_VERSION } from "../toolchain/node_modules/@modelcontextprotocol/sdk/dist/esm/types.js";
const client = new Client({name: "close-check", version: "1.0.0"});
const url = new URL("https://example.invalid/mcp");
const failed = new StreamableHTTPClientTransport(url, {fetch: async () => new Response("unavailable", {status: 500})});
await assert.rejects(client.connect(failed), {code: 500});
await client.close();
let initialized = false;
const good = new StreamableHTTPClientTransport(url, {fetch: async (_url, init) => {
  const message = JSON.parse(init.body);
  if (message.method !== "initialize") return new Response(null, {status: 202});
  initialized = true;
  return new Response(JSON.stringify({jsonrpc: "2.0", id: message.id, result: {
    protocolVersion: LATEST_PROTOCOL_VERSION, capabilities: {}, serverInfo: {name: "check", version: "1.0.0"}
  }}), {status: 200, headers: {"Content-Type": "application/json"}});
}});
await client.connect(good);
assert.equal(initialized, true);
await client.close();
console.log(JSON.stringify({real_http_failure_then_close_then_client_reuse: "passed", network_calls: 0}));
